package com.fincore.fincore.account; import java.math.BigDecimal; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.fincore.fincore.exception.*; import com.fincore.fincore.user.UserRepository; @Service public class AccountService { private final AccountRepository accounts; private final UserRepository users; public AccountService(AccountRepository a,UserRepository u){accounts=a;users=u;} @Transactional public AccountResponse create(Long uid,CreateAccountRequest r){var u=users.findById(uid).orElseThrow(()->new NotFoundException("User not found"));return AccountResponse.from(accounts.save(new Account(r.name().trim(),r.accountType(),r.openingBalance(),u)));} @Transactional(readOnly=true) public List<AccountResponse> all(Long uid){return accounts.findAllByUserIdOrderByCreatedAtDesc(uid).stream().map(AccountResponse::from).toList();} @Transactional(readOnly=true) public AccountResponse one(Long uid,Long id){return AccountResponse.from(accounts.findByIdAndUserId(id,uid).orElseThrow(()->new NotFoundException("Account not found")));} @Transactional public void transfer(Long uid,TransferRequest r){if(r.fromAccountId().equals(r.toAccountId()))throw new BadRequestException("Source and destination accounts must differ"); long first=Math.min(r.fromAccountId(),r.toAccountId()),second=Math.max(r.fromAccountId(),r.toAccountId()); Account a=accounts.findByIdForUpdate(first).orElseThrow(()->new NotFoundException("Account not found")),b=accounts.findByIdForUpdate(second).orElseThrow(()->new NotFoundException("Account not found")); Account from=a.getId().equals(r.fromAccountId())?a:b,to=a.getId().equals(r.toAccountId())?a:b; if(!from.getUser().getId().equals(uid))throw new ForbiddenException("You do not own the source account"); if(from.getBalance().compareTo(r.amount())<0)throw new BadRequestException("Insufficient funds");from.setBalance(from.getBalance().subtract(r.amount()));to.setBalance(to.getBalance().add(r.amount()));} }
